import 'package:flutter/material.dart'; import 'package:flutter_riverpod/flutter_riverpod.dart'; import 'package:go_router/go_router.dart'; import '../email_agent_providers.dart'; import '../data/email_agent_models.dart';
class EmailAgentScreen extends ConsumerWidget { const EmailAgentScreen({super.key}); @override Widget build(BuildContext c,WidgetRef r){final state=r.watch(emailAgentProvider),policy=r.watch(emailPolicyProvider);return Scaffold(appBar:AppBar(title:const Text('Email Agent')),body:ListView(padding:const EdgeInsets.all(20),children:[state.when(loading:()=>const LinearProgressIndicator(),error:(e,_)=>Text('$e'),data:(s)=>Card(child:ListTile(title:Text(s.active?'Active':'Paused'),subtitle:Text(s.connected?'${s.provider} connected':'Email provider is not connected.\nReplies can be prepared and routed for approval, but external email delivery requires a connected provider.'),trailing:FilledButton(onPressed:()async{await r.read(emailAgentRepositoryProvider).setStatus(s.active?'paused':'active');r.invalidate(emailAgentProvider);},child:Text(s.active?'Pause':'Activate'))))),const SizedBox(height:12),policy.when(loading:()=>const SizedBox(),error:(e,_)=>Text('$e'),data:(p)=>_Policy(policy:p,onSave:(v)async{await r.read(emailAgentRepositoryProvider).updatePolicy(v);r.invalidate(emailPolicyProvider);})),const SizedBox(height:12),FilledButton(onPressed:()async{final result=await r.read(emailAgentRepositoryProvider).run();if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text(result.noWork?'No pending Email work.':result.escalated?'Email escalated.':result.approvalRequested?'Prepared reply awaiting approval.':result.preparedReplyId!=null?'Prepared reply.':'${result.skipped??'Run complete.'}')));},child:const Text('Run Email Agent')),TextButton(onPressed:()=>c.go('/inbox'),child:const Text('Open Unified Inbox'))]));}}
class _Policy extends StatefulWidget{const _Policy({required this.policy,required this.onSave});final EmailAgentPolicy policy;final Future<void> Function(EmailAgentPolicy) onSave;@override State<_Policy> createState()=>_PolicyState();} class _PolicyState extends State<_Policy>{late bool a,c,s;late String tone;@override void initState(){super.initState();a=widget.policy.automaticReplies;c=widget.policy.complaintsEscalate;s=widget.policy.sensitiveApproval;tone=widget.policy.tone;}@override Widget build(BuildContext context)=>Card(child:Column(children:[SwitchListTile(title:const Text('Automatic replies'),value:a,onChanged:(v)=>setState(()=>a=v)),SwitchListTile(title:const Text('Escalate complaints'),value:c,onChanged:(v)=>setState(()=>c=v)),SwitchListTile(title:const Text('Sensitive replies require approval'),value:s,onChanged:(v)=>setState(()=>s=v)),DropdownButton<String>(value:tone,items:const['professional','friendly','formal'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>setState(()=>tone=v??tone)),TextButton(onPressed:()=>widget.onSave(EmailAgentPolicy.fromJson({'automatic_replies_enabled':a,'complaints_escalate':c,'sensitive_replies_require_approval':s,'default_tone':tone})),child:const Text('Save policy'))]));}
